// Native Soul Business shell, based on the supplied screenshots. All operations are simulated.
(() => {
const oldBusiness=renderBusiness;
const sbIcon=(name,size=15)=>{const shapes={grid:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M9 9v12"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',alert:'<path d="m12 3 10 18H2L12 3Z"/><path d="M12 9v5m0 3v1"/>'};return shapes[name]?`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">${shapes[name]}</svg>`:icon(name==='home'?'house':name,size)};
const org='Instituto Infantil Cordeirinho LTDA';
const nav=(label,page,glyph='grid')=>`<button type="button" data-bpage="${page}" class="${(state.businessPage||'home')===page?'selected':''}">${sbIcon(glyph,15)}<span>${label}</span></button>`;
const action=(label,act,cls='sb-button')=>`<button type="button" class="${cls}" data-action="${act}">${label}</button>`;
const link=(label,page,cls='sb-button')=>`<button type="button" class="${cls}" data-bpage="${page}">${label}</button>`;
const notice=(label)=>action(label,'prototype-notice');
const metrics=(items)=>`<div class="sb-metrics">${items.map(([label,value])=>`<article><span>${label}</span><strong>${value}</strong></article>`).join('')}</div>`;
const heading=(title,extra='')=>`<div class="sb-heading"><h2>${title}</h2>${extra}</div>`;
const table=(cols,body)=>`<div class="sb-table-wrap"><table><thead><tr>${cols.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`;
const empty=(cols,text)=>`<tr><td colspan="${cols}" class="sb-empty">${text}</td></tr>`;
const balance=()=>`<section class="sb-card sb-balance"><div><span>Saldo</span><strong>R$ 10,00</strong><small>Total disponível na sua conta · demonstração</small></div><button class="sb-button" data-bmodal="credit">+ Adicionar crédito</button></section>`;
function home(){const m=campaignMetrics();return `<h1>Olá, Carlos</h1><p>Você está na ${org}</p><div class="sb-alert">${sbIcon('alert',15)}<div>Saldo Baixo!<small>Seu saldo está quase acabando. Adicione créditos para evitar a pausa das campanhas.</small></div></div>${balance()}${heading('Dashboard',`<div>${notice('▦ Período')} ${link('+ Criar anúncio','create','sb-button primary')}</div>`)}${[['Anúncios',[['Custo','R$ 0,00'],['Impressões','0'],['Cliques','0'],['CTR médio','0,00%']],'ads'],['Soul Play',[['Visualizações','0'],['Cadastros','0'],['Pontos distribuídos','0'],['Acessos ao site','0']],'play'],['SoulMove',[['Participantes',m.participants],['Jornadas elegíveis',m.validated],['Benefícios emitidos',m.benefits],['Compras confirmadas',m.conversions]],'move']].map(([title,items,page])=>`<div class="sb-section-label">${title}${page==='move'?'<span>Campanha VIVA · dados simulados</span>':''}</div><section class="sb-summary sb-card">${metrics(items)}${link('Ver tudo<br><b>→</b>',page)}</section>`).join('')}`}
function ads(){return `<h1>${org}</h1>${heading('Campanhas',link('+ Criar campanha','create','sb-button primary'))}<div class="sb-tabs">${link('Anúncios','ads','active')}${link('SoulMove','move','')}</div>${metrics([['Todas',1],['Pendentes',1],['Ativas',0],['Pausadas',0],['Encerradas',0]])}<section class="sb-card"><p>Mostrando <select aria-label="Registros"><option>10</option></select> registros</p>${table(['Campanha','Formato','CTR','Custo','Cliques','Impressões','Status','Ações'],`<tr><td>Matrículas 2027 — Colégio Cordeiro<small>04/10/2026</small></td><td>Moments</td><td>0%</td><td>R$ 0,00</td><td>0</td><td>0</td><td><span class="sb-badge pending">Pendente</span></td><td>${notice('Ver detalhes')}</td></tr>`)}<small>Mostrando 1 a 1 de 1 registros</small></section>${heading('Resumo total',notice('▦ Período'))}<div class="sb-report-grid">${[['Custo total','R$ 0,00'],['Impressões','0'],['Cliques','0'],['CTR médio','0,00%'],['CPC','R$ 0,00'],['CPM','R$ 0,00'],['Conversões','0'],['Custo por resultado','R$ 0,00'],['Pontos utilizados','Pts 0']].map(([k,v])=>`<article class="sb-card"><span>${k}</span><strong>${v}</strong></article>`).join('')}</div>`}
function wallet(){return `<h1>${org}</h1><h2>Carteira</h2><p>Gerencie seus créditos e pontos Soul para investir em campanhas.</p>${balance()}<section class="sb-card"><h3>Dados de pagamento</h3><p class="sb-muted">Nenhum cartão salvo. Adicione crédito para salvar um cartão.</p></section>${heading('Movimentações da Carteira')}<section class="sb-card">${table(['Data/Hora','Tipo','Descrição','Valor','Status'],empty(5,'Nenhuma movimentação encontrada'))}<small>Mostrando 0 registros</small></section>${metrics([['Investimento total','R$ 0,00'],['Retorno (ROI médio)','0%'],['Campanhas ativas','0'],['Total de gastos','R$ 0,00']])}`}
function points(){return `<h1>${org}</h1><p>Gerencie seus créditos e pontos Soul para usar em campanhas.</p><div class="sb-point-info">${[['Conheça os Pontos','Os pontos Soul funcionam como créditos para veiculação de campanhas na plataforma SoulUP.'],['O que são os Pontos?','É a moeda de veiculação do SoulUp Ads. Use seus pontos para criar e distribuir campanhas.'],['Como ganhar?','Finalize o preenchimento do seu perfil, indique amigos e participe dos programas de benefícios.'],['Valor do ponto','Cada ponto Soul equivale a R$ 0,03 na referência do painel Ads.']].map(([t,d])=>`<article class="sb-card"><h3>${t}</h3><p>${d}</p></article>`).join('')}</div><section class="sb-card sb-balance"><div><span>Pontos disponíveis</span><strong>0 <small>pts</small></strong><small>0 no período anterior</small></div><div><button class="sb-button primary" data-bmodal="recharge">Nova Recarga</button> <button class="sb-button" data-bmodal="distribute">Distribuir</button></div></section>${['Movimentação de compra','Distribuição','Evolução anual'].map((s,i)=>`${heading(s)}<section class="sb-card"><p>${i===2?'Acompanhe suas compras e utilizações mês a mês.':'Mostrando 5 registros'}</p><div class="sb-empty">${i===0?'Nenhuma compra realizada ainda.':i===1?'Nenhuma distribuição realizada ainda.':'Nenhuma movimentação registrada neste ano.'}</div></section>`).join('')}`}
function companies(){return `<h1>${org}</h1>${heading('Contas Corporativas',notice('+ Nova empresa'))}<section class="sb-card"><p>Mostrando 10 registros</p>${table(['Nome','Permissão','CNPJ','Último acesso','Ações'],`<tr><td>${org}<small>Conta demonstrativa</small></td><td><span class="sb-badge">Dono</span></td><td>Não exibido no protótipo</td><td>03/10/2026</td><td>${notice('Visualizar')}</td></tr>`)}</section>`}
function play(){return `<h1>${org}</h1><h2>Criar canal</h2><p>Na Soul Play você pode oferecer vídeos patrocinados através de um QR Code para engajar seus usuários.</p><section class="sb-card sb-form"><label>Nome do canal<input placeholder="Digite o nome do canal"></label>${['Logo da empresa','Imagem do banner'].map(t=>`<label>${t}</label><div class="sb-upload"><p>Selecione uma imagem para o canal.</p>${notice('Selecionar arquivo')}</div>`).join('')}</section><div class="sb-end">${notice('Próximo')}</div>`}
function create(){const step=state.sbStep||1;return `<div class="sb-wizard"><h1>${org}</h1><h2>Criar anúncio ${state.sbDraft?.saved?'<span class="sb-badge">Rascunho salvo</span>':''}</h2><p>Siga o passo a passo abaixo para criar um novo anúncio.</p><progress value="${step}" max="4"></progress><small class="sb-end">Passo ${step}/4</small><section class="sb-card sb-form">${step===1?`<h2>Dados da campanha</h2><label>Nome da campanha<input data-bfield="title" value="${escapeHtml(state.sbDraft?.title||'')}" placeholder="Digite o nome da campanha"></label><label>Objetivo</label><div class="sb-option">◉ Visualização<p>Converter o maior número de visualização em seu anúncio.</p></div><label>Descrição da campanha (opcional)<textarea data-bfield="description" rows="5">${escapeHtml(state.sbDraft?.description||'')}</textarea></label>`:step===2?`<h2>Público da campanha</h2><h3>Gênero e idade</h3><div class="sb-form-row"><label>Gênero<select><option>Ambos</option><option>Feminino</option><option>Masculino</option></select></label><label>Idade De<input type="number" value="18" min="18"></label><label>Idade Até<input type="number" value="65" min="18"></label></div><h3>Localização</h3><div class="sb-form-row"><label>País<select><option>Brasil</option></select></label><label>Estado<select><option>São Paulo</option></select></label></div><h3>Classificação do conteúdo</h3><div class="sb-option">◉ Livre para todos</div>`:step===3?`<h2>Dados do anúncio</h2><label>Formato<select><option>Moments</option><option>Vídeo</option></select></label><div class="sb-upload"><p>Adicione a imagem do seu anúncio</p>${notice('Selecionar arquivo')}</div><label>Título<input placeholder="Título do anúncio"></label><label>Chamada para ação<select><option>Saiba mais</option></select></label>`:`<h2>Revisão da campanha</h2><p>${escapeHtml(state.sbDraft?.title||'Nova campanha')}</p><div class="sb-option">Rascunho demonstrativo. Nenhuma campanha real será publicada ou cobrada.</div>`}</section><div class="sb-card sb-wizard-actions"><button class="sb-button" data-bsave>Salvar rascunho</button><div><button class="sb-button" data-bstep="${Math.max(1,step-1)}">‹ Voltar</button> <button class="sb-button primary" ${step===4?'data-bsave':`data-bstep="${step+1}"`}>${step===4?'Salvar rascunho':'Próximo'}</button></div></div></div>`}
function move(){const content=oldBusiness().match(/<main class="business-main">([\s\S]*?)<\/main>/)[1];return `<div class="sb-breadcrumb">Campanhas / SoulMove</div><div class="sb-tabs">${action('Visão geral','business-home',state.businessView==='overview'||!state.businessView?'active':'')}${action('Configurar campanha','configure-campaign',state.businessView==='config'?'active':'')}${action('Encerramento e relatório','close-campaign-view',state.businessView==='closing'?'active':'')}</div><div class="sb-move">${content}</div>`}
function modal(){const id=state.sbModal;if(!id)return '';return `<div class="sb-modal-backdrop"><section class="sb-modal" role="dialog" aria-modal="true" aria-labelledby="sb-modal-title"><button class="sb-close" data-bclose aria-label="Fechar">×</button><h2 id="sb-modal-title">${id==='credit'?'Adicionar créditos':id==='recharge'?'Nova Recarga':'Distribuir pontos'}</h2><p>${id==='distribute'?'Informe os dados da distribuição.':'Escolha o valor e a forma de pagamento.'}</p><label>${id==='distribute'?'Quantidade de pontos':'Valor (R$)'}<input type="number" min="1" value="${id==='credit'?300:100}"></label>${id==='distribute'?'<label>Destino<input placeholder="Campanha de destino"></label>':'<label>Método de pagamento<select><option>PIX</option><option>Cartão de crédito</option><option>Boleto</option></select></label>'}<p class="sb-muted">Demonstração: nenhum pagamento ou envio será realizado.</p><div class="sb-end"><button class="sb-button" data-bclose>Cancelar</button> <button class="sb-button primary" data-bconfirm>Continuar</button></div></section></div>`}
renderBusiness=function(){const page=state.businessPage||'home';const pages={home,ads,wallet,points,companies,play,create,move};return `<div class="sb-app"><header class="sb-header"><button class="sb-logo" data-bpage="home" aria-label="Soul Business Home">soul<small>business</small></button><div class="sb-search">${icon('search',15)}<input aria-label="Pesquisar páginas" placeholder="Pesquisar" id="sb-search"></div><div class="sb-account"><button class="sb-bell" data-action="prototype-notice" aria-label="Notificações">${sbIcon('bell')}</button><span>${icon('users',18)}</span><div>Instituto Infantil…<small>Empresa</small></div><span>⌄</span></div></header><aside class="sb-sidebar"><nav aria-label="Soul Business">${nav('Home','home','home')}${nav('Campanhas','ads','grid')}<div class="sb-subnav">${nav('Anúncios','ads','grid')}${nav('SoulMove','move','route')}</div>${nav('Carteira','wallet','wallet')}${nav('Soul Play','play','play')}${nav('Pontos Soul','points','badge')}${nav('Empresas','companies','users')}</nav><small class="sb-demo">Ambiente demonstrativo</small></aside><main class="sb-main">${(pages[page]||home)()}</main>${modal()}</div>`};
document.addEventListener('click',e=>{const el=e.target.closest('[data-bpage],[data-bmodal],[data-bclose],[data-bconfirm],[data-bstep],[data-bsave]');if(!el)return;e.preventDefault();e.stopImmediatePropagation();if(el.dataset.bpage){state.businessPage=el.dataset.bpage;if(state.businessPage==='move')state.businessView='overview';state.sbModal=null;}if(el.dataset.bmodal)state.sbModal=el.dataset.bmodal;if(el.hasAttribute('data-bclose'))state.sbModal=null;if(el.hasAttribute('data-bconfirm')){state.sbModal=null;showToast('Simulação concluída. Nenhuma operação financeira foi realizada.')}if(el.dataset.bstep)state.sbStep=Number(el.dataset.bstep);if(el.hasAttribute('data-bsave')){state.sbDraft||={};state.sbDraft.saved=true;showToast('Rascunho salvo nesta sessão demonstrativa. Nenhum anúncio publicado.')}render()},true);
document.addEventListener('input',e=>{if(e.target.dataset.bfield){state.sbDraft||={};state.sbDraft[e.target.dataset.bfield]=e.target.value}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.sbModal){state.sbModal=null;render()}if(e.key==='Enter'&&e.target.id==='sb-search'){const q=e.target.value.toLowerCase();const item=[['soulmove','move'],['mobilidade','move'],['campanha','ads'],['carteira','wallet'],['pontos','points'],['empresa','companies'],['play','play'],['home','home']].find(([name])=>name.includes(q)||q.includes(name));if(item&&q){state.businessPage=item[1];render()}else showToast('Pesquise Home, Campanhas, SoulMove, Carteira, Soul Play, Pontos Soul ou Empresas.')}});
render();
})();
